function extractPathsFromSvg(file) {
  const content = fs.readFileSync(file, "utf8");
  const re = /<path[^>]*\bd="([^"]+)"/g;
  const paths = [];
  let m;
  while ((m = re.exec(content))) paths.push(m[1]);
  return paths;
}

function extractPathsBetween(file, startMarker, endMarker) {
  const content = fs.readFileSync(file, "utf8");
  const startIdx = content.indexOf(startMarker);
  const endIdx = endMarker ? content.indexOf(endMarker, startIdx) : content.length;
  const slice = content.slice(startIdx, endIdx === -1 ? content.length : endIdx);
  const re = /d="([^"]+)"/g;
  const paths = [];
  let m;
  while ((m = re.exec(slice))) paths.push(m[1]);
  return paths;
}

