describe('ZimmCartButtonGroup recipe — no compensating gap when the express buttons are removed (AC2)', () => {
  test('sets no fixed height/minHeight — a flex `gap` collapses on its own when a child is removed', () => {
    const base = ZimmCartButtonGroupRecipe.baseStyle as Record<string, unknown>;
    expect(base).not.toHaveProperty('height');
    expect(base).not.toHaveProperty('minHeight');
    expect(base.display).toBe('flex');
    expect(base.flexDirection).toBe('column');
  });

  test('gap resolves to the actionSizes.gap token (16px) by reference, not a re-typed literal', () => {
    const base = ZimmCartButtonGroupRecipe.baseStyle as Record<string, unknown>;
    expect(base.gap).toBe('var(--zimm-size-action-gap)');
    // Closes the loop: the var name alone only proves the *recipe* references a token; this
    // confirms that CSS var is itself derived from actionSizes.gap in zimmTokens.ts, not an
    // independently re-typed 16px literal living in two places.
    expect(zimmTokens['--zimm-size-action-gap']).toBe(actionSizes.gap);
    expect(actionSizes.gap).toBe('16px');
  });
});

describe('ZimmCartButtonGroup — Checkout button, ZimmButton "primary" states (pass criterion 3)', () => {
  test('default: grey[900] bg (text.default alias), white text (text.inverse alias)', () => {
    // Button.variants is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts
    // always passes a variants object — guaranteed non-null at runtime.
    const primary = Button.variants!.primary as Record<string, unknown>;
    expect(primary.bg).toBe('var(--zimm-color-text-default)');
    expect(primary.color).toBe('var(--zimm-color-text-inverse)');
  });

  test('uppercase is inherited from the `button` textStyle, not set independently here', () => {
    // Button.sizes is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts
    // always passes a sizes object — guaranteed non-null at runtime.
    const lg = Button.sizes!.lg as Record<string, unknown>;
    expect(lg.textStyle).toBe('button');
  });

  test('h52 / px32 resolve from actionSizes tokens via zimmTokens.ts, not re-typed literals', () => {
    // Button.sizes is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts
    // always passes a sizes object — guaranteed non-null at runtime.
    const lg = Button.sizes!.lg as Record<string, unknown>;
    expect(lg.h).toBe('var(--zimm-size-action-height-lg)');
    expect(lg.px).toBe('var(--zimm-size-action-padding-h-lg)');
    expect(zimmTokens['--zimm-size-action-height-lg']).toBe(actionSizes.height.lg);
    expect(zimmTokens['--zimm-size-action-padding-h-lg']).toBe(actionSizes.paddingX.lg);
    expect(actionSizes.height.lg).toBe('52px');
    expect(actionSizes.paddingX.lg).toBe('32px');
  });

  test('minW is the documented 80px provisional constant', () => {
    // Button.sizes is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts
    // always passes a sizes object — guaranteed non-null at runtime.
    const lg = Button.sizes!.lg as Record<string, unknown>;
    expect(lg.minW).toBe('80px');
  });

  test('hover/active/disabled states exist and each differs from the default bg', () => {
    // Button.variants is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts
    // always passes a variants object — guaranteed non-null at runtime.
    const primary = Button.variants!.primary as Record<string, unknown>;
    expect(primary._hover).toBeDefined();
    expect(primary._active).toBeDefined();
    expect(primary._disabled).toBeDefined();
    expect((primary._hover as Record<string, unknown>).bg).not.toBe(primary.bg);
    expect((primary._active as Record<string, unknown>).bg).not.toBe(primary.bg);
    expect((primary._disabled as Record<string, unknown>).bg).not.toBe(primary.bg);
  });

  test('focus-visible outline genuinely differs from the default (resting) outline (WCAG 2.4.7) — inherited from baseStyle, since primary declares none of its own', () => {
    // zimmButton.css.ts's own comment on the primary variant: "Focus ring inherited from
    // baseStyle (2px offset), per Handover button.md" — unlike secondary (tested below), primary
    // has no _focusVisible key of its own; Chakra's deep-merge of baseStyle+variant is what makes
    // baseStyle's ring apply. Reading `primary._focusVisible` directly (as the secondary test
    // does) would be reading the wrong object for this specific variant.
    // Button.variants is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts
    // always passes a variants object — guaranteed non-null at runtime.
    const primary = Button.variants!.primary as Record<string, unknown>;
    const base = Button.baseStyle as Record<string, unknown>;
    const focusVisible = base._focusVisible as Record<string, unknown>;
    expect(primary._focusVisible).toBeUndefined();
    expect(primary.outline).toBeUndefined();
    expect(focusVisible.outline).toBe('var(--zimm-focus-ring)');
    expect(focusVisible.outline).not.toBe(primary.outline);
  });
});

describe('ZimmCartButtonGroup — Apple Pay / Google Pay, ZimmButton "secondary" states (pass criterion 4)', () => {
  test('default: transparent bg, grey[900] 1px border', () => {
    // Button.variants is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts
    // always passes a variants object — guaranteed non-null at runtime.
    const secondary = Button.variants!.secondary as Record<string, unknown>;
    expect(secondary.bg).toBe('transparent');
    expect(secondary.borderColor).toBe('var(--zimm-color-text-default)');
  });

  test('hover/active/disabled states exist and each differs from the default', () => {
    // Button.variants is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts
    // always passes a variants object — guaranteed non-null at runtime.
    const secondary = Button.variants!.secondary as Record<string, unknown>;
    expect(secondary._hover).toBeDefined();
    expect(secondary._active).toBeDefined();
    expect(secondary._disabled).toBeDefined();
    expect((secondary._hover as Record<string, unknown>).bg).not.toBe(secondary.bg);
    expect((secondary._disabled as Record<string, unknown>).borderColor).not.toBe(secondary.borderColor);
  });

  test('focus-visible outline genuinely differs from the default (resting) outline (WCAG 2.4.7)', () => {
    // Button.variants is typed optional by Chakra's defineStyleConfig, but zimmButton.css.ts
    // always passes a variants object — guaranteed non-null at runtime.
    const secondary = Button.variants!.secondary as Record<string, unknown>;
    const focusVisible = secondary._focusVisible as Record<string, unknown>;
    expect(secondary.outline).toBeUndefined();
    expect(focusVisible.outline).toBe('var(--zimm-focus-ring)');
    expect(focusVisible.outline).not.toBe(secondary.outline);
  });

  test('Apple Pay and Google Pay each carry their own accessible name via aria-label', () => {
    mockUseCountryConfig.mockReturnValue({ checkoutOwner: 'sfcc' });
    renderGroup();
    expect(screen.getByRole('button', { name: APPLE_PAY_NAME })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: GOOGLE_PAY_NAME })).toBeInTheDocument();
  });

  // Coordinator-confirmed Design-fidelity fix (live Figma screenshot of the real button-group
  // frame, node 9323:95939): both marks are icon-only, no separate visible caption. `ZimmButton`'s
  // `hideLabelVisually` prop (added for this exact case — see its own JSDoc) keeps the label text
  // as a real DOM node for the accessible name while removing it from the rendered visual.
  test('Apple Pay and Google Pay labels are present in the DOM but not visually rendered (icon-only, per Figma)', () => {
    mockUseCountryConfig.mockReturnValue({ checkoutOwner: 'sfcc' });
    renderGroup();

    const appleLabel = screen.getByText(APPLE_PAY_NAME);
    const googleLabel = screen.getByText(GOOGLE_PAY_NAME);
    // Still real, readable text nodes — a screen reader (or this DOM query) can still find them.
    expect(appleLabel).toBeInTheDocument();
    expect(googleLabel).toBeInTheDocument();
    // But rendered via Chakra's standard sr-only clip technique, not shown on screen.
    [appleLabel, googleLabel].forEach((label) => {
      const computed = getComputedStyle(label);
      expect(computed.position).toBe('absolute');
      expect(computed.width).toBe('1px');
      expect(computed.height).toBe('1px');
      expect(computed.overflow).toBe('hidden');
    });
  });

  test('the accessible name still resolves correctly even though the visible label is hidden', () => {
    mockUseCountryConfig.mockReturnValue({ checkoutOwner: 'sfcc' });
    renderGroup();
    // getByRole's accessible-name computation would fail here if hideLabelVisually had silently
    // broken naming — proves aria-label (set unconditionally on ZimmButton) is what's actually
    // carrying the name, independent of the visible/hidden state of the label span.
    expect(screen.getByRole('button', { name: APPLE_PAY_NAME })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: GOOGLE_PAY_NAME })).toBeInTheDocument();
  });

  test('the Checkout button label stays genuinely visible, not hidden — it is real Figma button text, not a mark', () => {
    mockUseCountryConfig.mockReturnValue({ checkoutOwner: 'sfcc' });
    renderGroup();
    const checkoutLabel = screen.getByText(CHECKOUT_NAME);
    expect(getComputedStyle(checkoutLabel).position).not.toBe('absolute');
  });
});

describe('ZimmCartButtonGroup — error-in-cart (ACs 3/4): all three render enabled, zero feedback copy', () => {
  beforeEach(() => {
    mockUseCountryConfig.mockReturnValue({ checkoutOwner: 'sfcc' });
  });

  test('none of the three buttons is disabled — this component has no error-driven disabling logic at all', () => {
    renderGroup();
    const buttons = screen.getAllByRole('button');
    expect(buttons).toHaveLength(3);
    buttons.forEach((button) => {
      expect(button).not.toBeDisabled();
      expect(button).not.toHaveAttribute('aria-disabled', 'true');
    });
  });

  test('no feedback/error copy exists anywhere in the component — only the three button names render', () => {
    const { container } = renderGroup();
    expect(container.textContent).toBe(`${CHECKOUT_NAME}${APPLE_PAY_NAME}${GOOGLE_PAY_NAME}`);
  });
});

import React from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { MemoryRouter } from 'react-router-dom';
import { MultiSiteProvider } from '@salesforce/retail-react-app/app/contexts';
import { ZimmCartButtonGroup } from '.';

// Real generated site/locale pairs (overrides/app/config/countries.generated.ts) — useCountryConfig
// matches on BOTH sfccSiteId and locale, and silently falls back to AU on any mismatch, so getting
// these exactly right matters for the International story to actually exercise checkoutOwner
// 'global-e' rather than quietly rendering the domestic layout instead.
const AU_SITE = { id: 'ZimmermannAU', sfccSiteId: 'ZimmermannAU' };
const AU_LOCALE = { id: 'en' };
const HK_SITE = { id: 'ZimmermannHK', sfccSiteId: 'ZimmermannHK' };
const HK_LOCALE = { id: 'en-HK' };

const meta: Meta<typeof ZimmCartButtonGroup> = {
  title: 'Commerce/ZimmCartButtonGroup',
  component: ZimmCartButtonGroup,
  parameters: { layout: 'padded' },
};

export default meta;

type Story = StoryObj<typeof ZimmCartButtonGroup>;

/** Domestic (AU, checkoutOwner 'sfcc') — all three buttons in fixed order (AC1). */
export const Default: Story = {
  decorators: [
    (Story) => (
      <MemoryRouter>
        <MultiSiteProvider site={AU_SITE} locale={AU_LOCALE} buildUrl={(path: string) => path}>
          <Story />
        </MultiSiteProvider>
      </MemoryRouter>
    ),
  ],
};

/**
 * International (HK, checkoutOwner 'global-e') — express buttons removed, not hidden (AC2): only
 * the Checkout button renders, with no compensating gap/height left behind.
 */
export const International: Story = {
  decorators: [
    (Story) => (
      <MemoryRouter>
        <MultiSiteProvider site={HK_SITE} locale={HK_LOCALE} buildUrl={(path: string) => path}>
          <Story />
        </MultiSiteProvider>
      </MemoryRouter>
    ),
  ],
};

/**
 * SFCC-275 ACs 3/4 — a shopper's cart has a blocking error (e.g. a max-quantity-reached inline
 * message elsewhere in the drawer), but all three buttons still render enabled with no feedback
 * copy of their own: this component takes no error-related prop at all, so this story is
 * intentionally identical to Default — the point being demonstrated is the *absence* of any
 * error-driven disabling, not a distinct visual state. See index.test.tsx for the assertion that
 * backs this up mechanically rather than by inspection alone.
 */
export const ErrorInCart: Story = {
  decorators: [
    (Story) => (
      <MemoryRouter>
        <MultiSiteProvider site={AU_SITE} locale={AU_LOCALE} buildUrl={(path: string) => path}>
          <Story />
        </MultiSiteProvider>
      </MemoryRouter>
    ),
  ],
};

