async function loadStory(page, id) {
  const errors = [];
  page.removeAllListeners('console');
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });
  page.on('pageerror', (err) => errors.push('pageerror: ' + err.message));
  await page.goto(`${BASE}?id=${id}&viewMode=story`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  const bodyText = await page.locator('body').innerText().catch(() => '');
  const hasErrorBoundary = /something went wrong|error boundary|storybook.*crashed/i.test(bodyText);
  return { errors, hasErrorBoundary };
}

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });

  const results = {};

  // ---- Default (domestic) ----
  let r = await loadStory(page, 'commerce-zimmcartbuttongroup--default');
  const buttons = await page.locator('button').all();
  const names = [];
  for (const b of buttons) names.push((await b.getAttribute('aria-label')) || (await b.innerText()));
  results.domestic = { consoleErrors: r.errors, hasErrorBoundary: r.hasErrorBoundary, buttonCount: buttons.length, names };

  // group container height + gap
  const root = page.locator('#storybook-root > *').first();
  const rootBox = await root.boundingBox();
  const rootStyles = await root.evaluate((el) => {
    const cs = getComputedStyle(el);
    return { display: cs.display, flexDirection: cs.flexDirection, gap: cs.gap, width: cs.width };
  });
  results.domestic.rootBox = rootBox;
  results.domestic.rootStyles = rootStyles;

  // per-button computed height/padding + label visibility
  const btnDetails = [];
  for (let i = 0; i < buttons.length; i++) {
    const b = buttons[i];
    const box = await b.boundingBox();
    const cs = await b.evaluate((el) => {
      const s = getComputedStyle(el);
      return { height: s.height, paddingLeft: s.paddingLeft, paddingRight: s.paddingRight, bg: s.backgroundColor, border: s.border, textTransform: s.textTransform, color: s.color };
    });
    // find label span/svg inside
