  for (let i = 0; i < errCount; i++) disabledStates.push(await errButtons.nth(i).isDisabled());
  results.errorInCart = { consoleErrors: r.errors, buttonCount: errCount, disabledStates };

  // ---- ZimmButton HiddenLabel story ----
  r = await loadStory(page, 'elements-zimmbutton--hidden-label');
  const hlButton = page.locator('#storybook-root button').first();
  const hlName = await hlButton.getAttribute('aria-label');
  const hlText = await hlButton.innerText();
  await page.screenshot({ path: `${OUT}/hiddenlabel.png` });
  results.hiddenLabelStory = { consoleErrors: r.errors, ariaLabel: hlName, visibleInnerText: hlText };

  console.log(JSON.stringify(results, null, 2));
  await browser.close();
})().catch((e) => { console.error('SCRIPT ERROR:', e.message); process.exit(1); });
